      const link = root.matches('[data-cx-link-task], .ans-hyperlink') ? (root.matches('a') ? root : root.querySelector('a')) : null;
      if (link && enabled(link)) { record.done = true; link.click(); log('已打开链接任务，等待平台完成标记'); continue; }
